import React, { useState, useEffect } from 'react';
import { Box, Grid, Paper, Typography, Button, Card, CardContent, CircularProgress } from '@mui/material';
import DashboardLayout from '../../components/dashboard/DashboardLayout';
import Messages from '../../components/dashboard/Messages';
import Payments from '../../components/dashboard/Payments';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { collection, query, where, getDocs, orderBy } from 'firebase/firestore';
import { db } from '../../firebase/config';

const ClientDashboard = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    activeServices: 0,
    pendingRequests: 0,
    completedServices: 0,
    totalSpent: 0
  });
  const [recentActivity, setRecentActivity] = useState([]);

  useEffect(() => {
    const fetchUserData = async () => {
      if (!user) return;

      try {
        // Query for user's service requests
        const serviceRequestsRef = collection(db, 'serviceRequests');
        const q = query(
          serviceRequestsRef,
          where('userId', '==', user.uid),
          orderBy('createdAt', 'desc')
        );

        const querySnapshot = await getDocs(q);
        const requests = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));

        // Calculate stats
        const activeServices = requests.filter(req => req.status === 'in_progress').length;
        const pendingRequests = requests.filter(req => req.status === 'pending').length;
        const completedServices = requests.filter(req => req.status === 'completed').length;
        const totalSpent = requests.reduce((total, req) => {
          return total + (req.payment?.amount || 0);
        }, 0);

        setStats({
          activeServices,
          pendingRequests,
          completedServices,
          totalSpent
        });

        // Set recent activity (last 5 requests)
        setRecentActivity(requests.slice(0, 5));
        
      } catch (error) {
        console.error('Error fetching user data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, [user]);

  if (loading) {
    return (
      <DashboardLayout>
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '60vh' }}>
          <CircularProgress />
        </Box>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <Box sx={{ flexGrow: 1 }}>
        <Grid container spacing={3}>
          {/* Welcome Card */}
          <Grid item xs={12}>
            <Paper sx={{ p: 3, mb: 3, borderRadius: 2 }}>
              <Typography variant="h4" gutterBottom>
                Welcome back, {user?.displayName || user?.email || 'User'}!
              </Typography>
              <Typography variant="body1" color="text.secondary">
                Manage your services and track your requests from your personalized dashboard.
              </Typography>
            </Paper>
          </Grid>

          {/* Quick Stats */}
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography color="text.secondary" gutterBottom>
                  Active Services
                </Typography>
                <Typography variant="h4">{stats.activeServices}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography color="text.secondary" gutterBottom>
                  Pending Requests
                </Typography>
                <Typography variant="h4">{stats.pendingRequests}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography color="text.secondary" gutterBottom>
                  Completed Services
                </Typography>
                <Typography variant="h4">{stats.completedServices}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Card sx={{ height: '100%' }}>
              <CardContent>
                <Typography color="text.secondary" gutterBottom>
                  Total Spent
                </Typography>
                <Typography variant="h4">₹{stats.totalSpent.toLocaleString()}</Typography>
              </CardContent>
            </Card>
          </Grid>

          {/* Messages and Payments Section */}
          <Grid item xs={12} md={6}>
            <Messages />
          </Grid>
          <Grid item xs={12} md={6}>
            <Payments />
          </Grid>

          {/* Recent Activity */}
          <Grid item xs={12}>
            <Paper sx={{ p: 3, borderRadius: 2 }}>
              <Typography variant="h6" gutterBottom>
                Recent Activity
              </Typography>
              {recentActivity.length > 0 ? (
                <Box sx={{ mt: 2 }}>
                  {recentActivity.map((activity) => (
                    <Box
                      key={activity.id}
                      sx={{
                        p: 2,
                        mb: 1,
                        borderRadius: 1,
                        bgcolor: 'background.default',
                        '&:hover': { bgcolor: 'action.hover' }
                      }}
                    >
                      <Typography variant="subtitle1">
                        {activity.serviceTitle || 'Service Request'}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Status: {activity.status.charAt(0).toUpperCase() + activity.status.slice(1)}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {new Date(activity.createdAt?.seconds * 1000).toLocaleDateString()}
                      </Typography>
                    </Box>
                  ))}
                </Box>
              ) : (
                <Typography variant="body1" color="text.secondary">
                  No recent activity to display
                </Typography>
              )}
            </Paper>
          </Grid>

          {/* Quick Actions */}
          <Grid item xs={12}>
            <Paper sx={{ p: 3, borderRadius: 2 }}>
              <Typography variant="h6" gutterBottom>
                Quick Actions
              </Typography>
              <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                <Button 
                  variant="contained" 
                  color="primary"
                  onClick={() => navigate('/services')}
                >
                  Browse Services
                </Button>
                <Button 
                  variant="outlined" 
                  color="primary"
                  onClick={() => navigate('/support')}
                >
                  Contact Support
                </Button>
                <Button 
                  variant="outlined" 
                  color="primary"
                  onClick={() => navigate('/profile')}
                >
                  Update Profile
                </Button>
              </Box>
            </Paper>
          </Grid>
        </Grid>
      </Box>
    </DashboardLayout>
  );
};

export default ClientDashboard;